      es: ["Construido entre 1563 y 1597.", "Altitud sobre el nivel del mar: 1.788 metros.", "Superficie del complejo: aproximadamente 2 hectáreas.", "Número de frescos conservados: 15.", "Distancia desde Gondar: 75 kilómetros.", "Tiempo de construcción: unos 30 años."],
      pt: ["Construído entre 1563-1597.", "Altitude acima do nível do mar: 1788 metros.", "Área do complexo: cerca de 2 hectares.", "Número de frescos preservados: 15.", "Distância de Gondar: 75 quilómetros.", "Tempo de construção: aprox. 30 anos."],
      fr: ["Construit entre 1563 et 1597.", "Altitude au-dessus du niveau de la mer : 1788 mètres.", "Superficie du complexe : environ 2 hectares.", "Nombre de fresques conservées : 15.", "Distance de Gondar : 75 kilomètres.", "Durée de construction : environ 30 ans."],
